17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.ArrayList;
24	import java.util.Collection;
25	import java.util.List;
26	import java.util.Locale;
27	import java.util.regex.Pattern;
28	
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
39	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
40	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
68	     * at least one dot and no whitespace on either side.
69	     */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        validateRequiredFields(ownerFieldsDto);
120	        normalizeTelephone(ownerFieldsDto);
121	        rejectDuplicateTelephone(ownerFieldsDto);
122	        rejectDuplicateHousehold(ownerFieldsDto);
123	        normalizeEmail(ownerFieldsDto);
124	        defaultRegistrationDate(ownerFieldsDto);
125	        HttpHeaders headers = new HttpHeaders();
126	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
127	        assignCustomerCode(owner);
128	        assignHousehold(owner, ownerFieldsDto);
129	        this.clinicService.saveOwner(owner);
130	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
131	        headers.setLocation(UriComponentsBuilder.newInstance()
132	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
133	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
139	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
140	        if (currentOwner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        currentOwner.setAddress(ownerFieldsDto.getAddress());
144	        currentOwner.setCity(ownerFieldsDto.getCity());
145	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
146	        currentOwner.setLastName(ownerFieldsDto.getLastName());
147	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
148	        normalizeEmail(ownerFieldsDto);
149	        currentOwner.setEmail(ownerFieldsDto.getEmail());
150	        this.clinicService.saveOwner(currentOwner);
151	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Transactional
156	    @Override
157	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        this.clinicService.deleteOwner(owner);
163	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        HttpHeaders headers = new HttpHeaders();
174	        Pet pet = petMapper.toPet(petFieldsDto);
175	        owner.setId(ownerId);
176	        pet.setOwner(owner);
177	        pet.getType().setName(null);
178	        this.clinicService.savePet(pet);
179	        PetDto petDto = petMapper.toPetDto(pet);
180	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
181	            .buildAndExpand(pet.getId()).toUri());
182	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
188	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
189	        if (currentOwner != null) {
190	            Pet currentPet = this.clinicService.findPetById(petId);
191	            if (currentPet != null) {
192	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
193	                currentPet.setName(petFieldsDto.getName());
194	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
195	                this.clinicService.savePet(currentPet);
196	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
197	            }
198	        }
199	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
205	        HttpHeaders headers = new HttpHeaders();
206	        Visit visit = visitMapper.toVisit(visitFieldsDto);
207	        Pet pet = new Pet();
208	        pet.setId(petId);
209	        visit.setPet(pet);
210	        this.clinicService.saveVisit(visit);
211	        VisitDto visitDto = visitMapper.toVisitDto(visit);
212	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
213	            .buildAndExpand(visit.getId()).toUri());
214	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
215	    }
216	
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
221	        Owner owner = this.clinicService.findOwnerById(ownerId);
222	        if (owner != null) {
223	            Pet pet = owner.getPet(petId);
224	            if (pet != null) {
225	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
226	            }
227	        }
228	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	    }
230	
231	    /**
232	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
233	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
234	     * does not catch). The names of all offending fields are collected so the caller receives a
235	     * 400 response whose {@code errors} array lists each one.
236	     */
237	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
238	        List<String> missingFields = new ArrayList<>();
239	        if (isBlank(ownerFieldsDto.getFirstName())) {
240	            missingFields.add("firstName");
241	        }
242	        if (isBlank(ownerFieldsDto.getLastName())) {
243	            missingFields.add("lastName");
244	        }
245	        if (isBlank(ownerFieldsDto.getAddress())) {
246	            missingFields.add("address");
247	        }
248	        if (isBlank(ownerFieldsDto.getCity())) {
249	            missingFields.add("city");
250	        }
251	        if (isBlank(ownerFieldsDto.getTelephone())) {
252	            missingFields.add("telephone");
253	        }
254	        if (!missingFields.isEmpty()) {
255	            throw new InvalidOwnerFieldsException(missingFields);
256	        }
257	    }
258	
259	    private static boolean isBlank(String value) {
260	        return value == null || value.trim().isEmpty();
261	    }
262	
263	    /**
264	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
265	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
266	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
267	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}. The E.164
268	     * string is written back onto the request so it is what gets stored and returned. Any value that
269	     * cannot form a valid E.164 number is rejected with a 400 response whose {@code errors} array
270	     * names {@code telephone}.
271	     */
272	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
273	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
274	    }
275	
276	    /**
277	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
278	     * (400) naming {@code telephone} when it cannot form a valid number.
279	     */
280	    private static String toE164(String telephone) {
281	        if (telephone == null) {
282	            throw new InvalidOwnerFieldsException(List.of("telephone"));
283	        }
284	        boolean hasCountryCode = telephone.trim().startsWith("+");
285	        String digits = telephone.replaceAll("\\D", "");
286	        String national;
287	        if (hasCountryCode) {
288	            national = digits;
289	        } else {
290	            if (digits.startsWith("0")) {
291	                digits = digits.substring(1);
292	            }
293	            national = "61" + digits;
294	        }
295	        if (!national.matches("[0-9]{8,15}")) {
296	            throw new InvalidOwnerFieldsException(List.of("telephone"));
297	        }
298	        return "+" + national;
299	    }
300	
301	    /**
302	     * Rejects creating an owner whose E.164 telephone is already used by any other owner. The
303	     * incoming value has already been converted to its E.164 form by {@link #normalizeTelephone};
304	     * each existing owner's stored telephone is converted the same way before comparison so numbers
305	     * that only differ in formatting still collide. A match results in a 409 response naming
306	     * {@code telephone}.
307	     */
308	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
309	        String telephone = ownerFieldsDto.getTelephone();
310	        for (Owner existing : this.clinicService.findAllOwners()) {
311	            if (telephone.equals(normalizeExisting(existing.getTelephone()))) {
312	                throw new DuplicateOwnerTelephoneException(telephone);
313	            }
314	        }
315	    }
316	
317	    /**
318	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
319	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
320	     */
321	    private static String normalizeExisting(String telephone) {
322	        try {
323	            return toE164(telephone);
324	        } catch (InvalidOwnerFieldsException ex) {
325	            return null;
326	        }
327	    }
328	
329	    /**
330	     * Rejects creating an owner whose {@code lastName} and {@code address} already belong to another
331	     * owner. Both fields are compared case-insensitively and with runs of whitespace collapsed to a
332	     * single space, so values that differ only in letter case or spacing still collide. When the
333	     * request opts in with {@code sharesHousehold} set to {@code true} the check is skipped, allowing
334	     * household members to share a name and address. A match results in a 409 response naming
335	     * {@code lastName} and {@code address}.
336	     */
337	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
338	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
339	            return;
340	        }
341	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
342	        String address = normalizeForComparison(ownerFieldsDto.getAddress());
343	        for (Owner existing : this.clinicService.findAllOwners()) {
344	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
345	                && address.equals(normalizeForComparison(existing.getAddress()))) {
346	                throw new DuplicateOwnerHouseholdException(
347	                    ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
348	            }
349	        }
350	    }
351	
352	    /**
353	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
354	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
355	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
356	     */
357	    private static String normalizeForComparison(String value) {
358	        if (value == null) {
359	            return "";
360	        }
361	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
362	    }
363	
364	    /**
365	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
366	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
367	     * written back onto the request so that is what gets stored and returned. A present but invalid
368	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
369	     */
370	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
371	        String email = ownerFieldsDto.getEmail();
372	        if (email == null) {
373	            return;
374	        }
375	        String trimmed = email.trim();
376	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
377	            throw new InvalidOwnerFieldsException(List.of("email"));
378	        }
379	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
380	    }
381	
382	    /**
383	     * Defaults an owner's {@code registrationDate} on create. When the caller supplies no value,
384	     * it is set to the server's current date so every owner is persisted with a registration date;
385	     * a value provided in the request is kept as-is. The date is stored and returned in ISO
386	     * {@code YYYY-MM-DD} format.
387	     */
388	    private void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
389	        if (ownerFieldsDto.getRegistrationDate() == null) {
390	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
391	        }
392	    }
393	
394	    /**
395	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'} where
396	     * {@code LAST3} is the upper-cased first three letters of {@code lastName} and {@code NNNN} is a
397	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
398	     * (e.g. {@code 'SMI-0007'}).
399	     */
400	    private void assignCustomerCode(Owner owner) {
401	        String lastName = owner.getLastName();
402	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
403	        int sequence = this.clinicService.findAllOwners().size() + 1;
404	        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
405	    }
406	
407	    /**
408	     * Assigns the new owner's {@code householdId} when the request opts in with
409	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
410	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
411	     * same way {@link #rejectDuplicateHousehold} matches). The household's members and the new owner
412	     * all end up carrying one stable shared identifier: if any existing member already has a
413	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
414	     * and address. Any existing member that is missing the identifier is updated so the whole
415	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
416	     * identifier is assigned.
417	     */
418	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
419	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
420	            return;
421	        }
422	        String lastName = normalizeForComparison(owner.getLastName());
423	        String address = normalizeForComparison(owner.getAddress());
424	        List<Owner> members = new ArrayList<>();
425	        for (Owner existing : this.clinicService.findAllOwners()) {
426	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
427	                && address.equals(normalizeForComparison(existing.getAddress()))) {
428	                members.add(existing);
429	            }
430	        }
431	        if (members.isEmpty()) {
432	            return;
433	        }
434	        String householdId = members.stream()
435	            .map(Owner::getHouseholdId)
436	            .filter(id -> id != null && !id.isBlank())
437	            .findFirst()
438	            .orElseGet(() -> newHouseholdId(lastName, address));
439	        owner.setHouseholdId(householdId);
440	        for (Owner member : members) {
441	            if (!householdId.equals(member.getHouseholdId())) {
442	                member.setHouseholdId(householdId);
443	                this.clinicService.saveOwner(member);
444	            }
445	        }
446	    }
447	
448	    /**
449	     * Derives a stable household identifier from the normalized last name and address: the first
450	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
451	     * owners in the same household therefore derive the same value regardless of creation order.
452	     */
453	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
454	        try {
455	            byte[] digest = MessageDigest.getInstance("SHA-256")
456	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
457	            StringBuilder hex = new StringBuilder(digest.length * 2);
458	            for (byte b : digest) {
459	                hex.append(String.format("%02x", b));
460	            }
461	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
462	        } catch (NoSuchAlgorithmException ex) {
463	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
464	        }
465	    }
466	}
